@Configuration
public class GatewayRoutingConfig {
    @Bean
    public RouteLocator customRouteLocator(
        RouteLocatorBuilder builder,
        RedisRateLimiter redisRateLimiter
    ) {
        return builder.routes()
            .route("order_service_route", r -> r
                .path("/api/v1/orders/**")
                .filters(f -> f
                    .stripPrefix(2)
                    .addRequestHeader("X-Gateway-Time", String.valueOf(System.currentTimeMillis()))
                    .requestRateLimiter(c -> c
                        .setRateLimiter(redisRateLimiter)
                        .setKeyResolver(exchange -> Mono.just(
                            exchange.getRequest().getHeaders().getFirst("X-User-Id")
                        ))
                    )
                    .circuitBreaker(c -> c
                        .setName("orderServiceCircuitBreaker")
                        .setFallbackUri("forward:/fallback/orders")
                    )
                )
                .uri("lb://ORDER-SERVICE")
            )
            .build();
    }
}

import express, { Request, Response } from 'express';

interface MobileHomeFeedDTO {
  user: { id: string; name: string };
  recentOrders: Array<{ id: string; status: string }>;
  recommendations: Array<{ sku: string; title: string }>;
}

export async function getMobileHomeFeed(req: Request, res: Response) {
  const userId = req.headers['x-user-id'] as string;

  // Execute concurrent downstream calls over internal network
  const [userResult, ordersResult, recsResult] = await Promise.allSettled([
    userServiceClient.getUserProfile(userId),
    orderServiceClient.getRecentOrders(userId),
    recommendationClient.getPersonalized(userId),
  ]);

  if (userResult.status === 'rejected') {
    return res.status(502).json({ error: 'Core user profile unavailable' });
  }

  const responseDTO: MobileHomeFeedDTO = {
    user: { id: userResult.value.id, name: userResult.value.displayName },
    recentOrders: ordersResult.status === 'fulfilled' ? ordersResult.value.slice(0, 3) : [],
    recommendations: recsResult.status === 'fulfilled' ? recsResult.value.slice(0, 5) : [],
  };

  return res.json(responseDTO);
}

package discovery

import (
    "fmt"
    "os"
    "os/signal"
    "syscall"
    "github.com/hashicorp/consul/api"
)

func RegisterService(serviceName, serviceID string, port int) error {
    config := api.DefaultConfig()
    client, err := api.NewClient(config)
    if err != nil {
        return err
    }

    registration := &api.AgentServiceRegistration{
        ID:      serviceID,
        Name:    serviceName,
        Port:    port,
        Address: "10.0.1.25", // Pod private IP
        Check: &api.AgentServiceCheck{
            HTTP:     fmt.Sprintf("http://10.0.1.25:%d/health", port),
            Interval: "10s",
            Timeout:  "3s",
            DeregisterCriticalServiceAfter: "30s",
        },
    }

    if err := client.Agent().ServiceRegister(registration); err != nil {
        return err
    }

    // Handle graceful deregistration on SIGTERM
    go func() {
        sigChan := make(chan os.Signal, 1)
        signal.Notify(sigChan, syscall.SIGINT, syscall.SIGTERM)
        <-sigChan
        client.Agent().ServiceDeregister(serviceID)
        os.Exit(0)
    }()

    return nil
}
